#include <gtest/gtest.h>

extern "C" {
#include "core/data_structures/cstring.h"
#include "core/types/gamesman_status.h"
#include "core/types/uwapi/partmove_array.h"
}

// ============================= PartmoveArrayInit =============================

TEST(PartmoveArrayTest, InitInitializesToZero) {
    PartmoveArray pa;
    // Fill with garbage first to ensure Init actually clears it
    pa.array = (Partmove *)0xDEADBEEF;
    pa.size = 100;
    pa.capacity = 200;

    PartmoveArrayInit(&pa);

    EXPECT_EQ(pa.array, nullptr) << "Array pointer should be null after init.";
    EXPECT_EQ(pa.size, 0) << "Size should be 0 after init.";
    EXPECT_EQ(pa.capacity, 0) << "Capacity should be 0 after init.";
}

// ========================= PartmoveArrayEmplaceBack =========================

TEST(PartmoveArrayTest, EmplaceBackSingleElement) {
    PartmoveArray pa;
    PartmoveArrayInit(&pa);

    CString autogui_move;
    CString formal_move;
    CString from;
    CString to;
    CString full;

    CStringInitCopyCharArray(&autogui_move, "auto");
    CStringInitCopyCharArray(&formal_move, "formal");
    CStringInitCopyCharArray(&from, "from_pos");
    CStringInitCopyCharArray(&to, "to_pos");
    CStringInitCopyCharArray(&full, "full_move");

    int status = PartmoveArrayEmplaceBack(&pa, &autogui_move, &formal_move,
                                          &from, &to, &full);

    EXPECT_EQ(status, kSuccess)
        << "EmplaceBack should return kSuccess on valid inputs.";
    EXPECT_EQ(pa.size, 1) << "Size should be 1 after one insertion.";
    EXPECT_EQ(pa.capacity, 1)
        << "Capacity should be at least 1 after first insertion.";
    ASSERT_NE(pa.array, nullptr) << "Array should not be null.";

    EXPECT_STREQ(pa.array[0].autogui_move.str, "auto");
    EXPECT_STREQ(pa.array[0].formal_move.str, "formal");
    EXPECT_STREQ(pa.array[0].from.str, "from_pos");
    EXPECT_STREQ(pa.array[0].to.str, "to_pos");
    EXPECT_STREQ(pa.array[0].full.str, "full_move");

    // Check ownership transfer (original CStrings should be null strings now)
    EXPECT_TRUE(CStringIsNull(&autogui_move))
        << "Original string should be moved.";
    EXPECT_TRUE(CStringIsNull(&formal_move))
        << "Original string should be moved.";
    EXPECT_TRUE(CStringIsNull(&from)) << "Original string should be moved.";
    EXPECT_TRUE(CStringIsNull(&to)) << "Original string should be moved.";
    EXPECT_TRUE(CStringIsNull(&full)) << "Original string should be moved.";

    PartmoveArrayDestroy(&pa);
}

TEST(PartmoveArrayTest, EmplaceBackTriggersExpansion) {
    PartmoveArray pa;
    PartmoveArrayInit(&pa);

    for (int i = 0; i < 5; ++i) {
        CString autogui_move = CStringGetNull();
        CString formal_move = CStringGetNull();
        CString from = CStringGetNull();
        CString to = CStringGetNull();
        CString full = CStringGetNull();

        CStringInitCopyCharArray(&autogui_move, "a");
        CStringInitCopyCharArray(&formal_move, "f");

        int status = PartmoveArrayEmplaceBack(&pa, &autogui_move, &formal_move,
                                              &from, &to, &full);
        EXPECT_EQ(status, kSuccess);
    }

    EXPECT_EQ(pa.size, 5) << "Size should be exactly 5 after 5 insertions.";
    EXPECT_GE(pa.capacity, 5) << "Capacity should be at least 5.";
    ASSERT_NE(pa.array, nullptr);

    for (int i = 0; i < 5; ++i) {
        EXPECT_STREQ(pa.array[i].autogui_move.str, "a");
        EXPECT_STREQ(pa.array[i].formal_move.str, "f");
        EXPECT_TRUE(CStringIsNull(&pa.array[i].from));
    }

    PartmoveArrayDestroy(&pa);
}

TEST(PartmoveArrayTest, EmplaceBackWithNullStrings) {
    PartmoveArray pa;
    PartmoveArrayInit(&pa);

    CString autogui_move = CStringGetNull();
    CString formal_move = CStringGetNull();
    CString from = CStringGetNull();
    CString to = CStringGetNull();
    CString full = CStringGetNull();

    CStringInitCopyCharArray(&autogui_move, "move1");
    CStringInitCopyCharArray(&formal_move, "Move 1");

    int status = PartmoveArrayEmplaceBack(&pa, &autogui_move, &formal_move,
                                          &from, &to, &full);
    EXPECT_EQ(status, kSuccess);

    EXPECT_EQ(pa.size, 1);
    EXPECT_TRUE(CStringIsNull(&pa.array[0].from))
        << "From should remain null if passed as null.";
    EXPECT_TRUE(CStringIsNull(&pa.array[0].to))
        << "To should remain null if passed as null.";
    EXPECT_TRUE(CStringIsNull(&pa.array[0].full))
        << "Full should remain null if passed as null.";

    PartmoveArrayDestroy(&pa);
}

// =========================== PartmoveArrayDestroy ===========================

TEST(PartmoveArrayTest, DestroyEmptyArray) {
    PartmoveArray pa;
    PartmoveArrayInit(&pa);

    // Destroying an empty array should be safe and not crash
    PartmoveArrayDestroy(&pa);

    EXPECT_EQ(pa.array, nullptr);
    EXPECT_EQ(pa.size, 0);
    EXPECT_EQ(pa.capacity, 0);
}
